const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define regions
  const northEthiopia = ee.Geometry.Rectangle([37, 12, 40, 14]);
  const southEthiopia = ee.Geometry.Rectangle([37, 4, 40, 6]);

  // Target period: Oct-Nov 2021
  const target2021 = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate('2021-10-01', '2021-12-01')
    .select('precipitation');

  // Check if 2021 data exists
  const size2021 = target2021.size().getInfo();
  if (size2021 === 0) {
    console.log('No CHIRPS data for Oct-Nov 2021');
    console.log('<answer>C1</answer>');
    return;
  }

  console.log(`2021 Images: ${size2021}`);

  // Sum precipitation for 2021
  const total2021 = target2021.sum();

  // Calculate for both regions
  const north2021 = total2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northEthiopia,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  const south2021 = total2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southEthiopia,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  // Baseline period: Oct-Nov for years 2000-2013
  const years = ee.List.sequence(2000, 2013);

  const baselineCollection = ee.ImageCollection(years.map(function(year) {
    const col = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(ee.Date.fromYMD(year, 10, 1), ee.Date.fromYMD(year, 12, 1))
      .select('precipitation')
      .sum();
    return col;
  }));

  const sizeBaseline = baselineCollection.size().getInfo();
  if (sizeBaseline === 0) {
    console.log('No CHIRPS data for baseline 2000-2013');
    console.log('<answer>C1</answer>');
    return;
  }

  console.log(`Baseline years: ${sizeBaseline}`);

  // Calculate mean of baseline totals
  const baselineMean = baselineCollection.mean();

  const northBaseline = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northEthiopia,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  const southBaseline = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southEthiopia,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  // Get values
  const north2021Val = await north2021.getInfo();
  const south2021Val = await south2021.getInfo();
  const northBaselineVal = await northBaseline.getInfo();
  const southBaselineVal = await southBaseline.getInfo();

  // Validation
  if (north2021Val === null || south2021Val === null || 
      northBaselineVal === null || southBaselineVal === null) {
    console.log('Calculation returned null values');
    console.log('<answer>C3</answer>');
    return;
  }

  if (north2021Val < 0 || south2021Val < 0 || 
      northBaselineVal < 0 || southBaselineVal < 0) {
    console.log('Invalid negative precipitation values');
    console.log('<answer>C3</answer>');
    return;
  }

  // Calculate relative differences
  const northRelDiff = (north2021Val - northBaselineVal) / northBaselineVal;
  const southRelDiff = (south2021Val - southBaselineVal) / southBaselineVal;

  console.log(`North 2021: ${north2021Val.toFixed(2)} mm`);
  console.log(`North Baseline: ${northBaselineVal.toFixed(2)} mm`);
  console.log(`North Rel Diff: ${(northRelDiff * 100).toFixed(1)}%`);
  console.log(`South 2021: ${south2021Val.toFixed(2)} mm`);
  console.log(`South Baseline: ${southBaselineVal.toFixed(2)} mm`);
  console.log(`South Rel Diff: ${(southRelDiff * 100).toFixed(1)}%`);

  // Answer: Did southern Ethiopia receive LESS rainfall relative to baseline?
  // "Less" means more negative or less positive relative difference
  if (southRelDiff < northRelDiff) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
